#!/usr/bin/env node
/**
 * Rewrites the `Sitemap:` line in build/robots.txt to the backend origin the
 * bundle was actually built against.
 *
 * The sitemap is generated by the backend, so its host is environment-specific.
 * Hardcoding it in public/robots.txt would advertise a stale URL in every
 * deployment except local. This runs after `react-scripts build`, uses the same
 * REACT_APP_API_BASE_URL the bundle was compiled with, and never proxies the
 * sitemap through the frontend.
 */
const fs = require('fs');
const path = require('path');

const DEFAULT_ORIGIN = 'http://localhost:8080';
const robotsPath = path.join(__dirname, '..', 'build', 'robots.txt');

function resolveOrigin(raw) {
  const value = (raw || '').trim();
  if (!value) return DEFAULT_ORIGIN;
  try {
    const url = new URL(value);
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      throw new Error('unsupported protocol');
    }
    return url.origin;
  } catch {
    // Fail loudly: a bad origin here would silently publish an unreachable
    // sitemap URL to crawlers.
    console.error(`[robots] REACT_APP_API_BASE_URL is not a valid HTTP(S) origin: "${value}"`);
    process.exit(1);
  }
}

if (!fs.existsSync(robotsPath)) {
  console.error(`[robots] ${robotsPath} not found; run this after the build.`);
  process.exit(1);
}

const origin = resolveOrigin(process.env.REACT_APP_API_BASE_URL);
const source = fs.readFileSync(robotsPath, 'utf8');
const updated = source.replace(/^Sitemap:.*$/m, `Sitemap: ${origin}/sitemap.xml`);

if (!/^Sitemap: /m.test(updated)) {
  console.error('[robots] no Sitemap: line found in robots.txt');
  process.exit(1);
}

fs.writeFileSync(robotsPath, updated);
console.log(`[robots] Sitemap -> ${origin}/sitemap.xml`);
